namespace Cyclic172;

internal sealed record Integration(bool SecondExit, double SpeedHeadroom, double ExitLeadMeters, bool UseRecourse = false, bool StabilizeRelease = false, double SecondExtraHeadroom = 0);
internal sealed record Review(double Time, double Reference, string Mode, FreeRacingAction Baseline,
    FreeRacingAction Chosen, double Blend, string Gate, int Forecasts, int Queries, double PredictionMilliseconds);

internal sealed class CyclicExit172(Policy172 baseline, Teacher a, Teacher b, Weights weights, Integration tuning,
    RiderSpec spec, TrackFrame frame, TrackStateSnapshot surface, WorldParameters parameters,
    float mass, float inertia, CyclicReference172 targets)
{
    private const double ReviewSeconds = .2;
    private const double ShortSeconds = .44;
    private const double CheckSeconds = .84;
    private const double SettleMeters = 11;
    private const double CoastMetersPerSecondSquared = .65;
    private const double PreviewAcceleration = 3.5;
    private const double PredictedSweepMeters = .65;
    private static readonly float[] SteerGrid = [-.12f, -.08f, -.04f, -.02f, -.01f, -.004f, 0,
        .004f, .01f, .02f, .04f, .08f, .12f];
    private readonly Boundary152 boundary = new(frame);
    private readonly PredictionBoundary147 cache = new(frame);
    private int forecasts, queries;
    private long predictionTicks;
    private FreeRacingAction? plannedRelease;
    private double releaseReview;
    private FreeRacingAction lastProposed;

    public void ObserveApplied(FreeRacingAction action)
    {
        if (action != lastProposed) plannedRelease = null;
    }

    public Review Choose(FreeRacingInput input, CrankClutch144 crank)
    {
        forecasts = queries = 0;
        predictionTicks = 0;
        double s = input.Rider.TotalReferenceMeters;
        var original = Baseline(input, crank);
        Trace173.Event("exit-original", new { input.Time, original });
        var fallback = tuning.UseRecourse && Math.Abs(input.Time - releaseReview) < 1e-8
            ? plannedRelease : null;
        plannedRelease = null;
        var visit = targets.Follow(s);
        var bend = new Bend(visit.Entry, visit.Exit);
        var next = visit.NextEntry;
        double lead = tuning.ExitLeadMeters;
        if (s < bend.Exit - lead - input.Rider.Speed * .35 ||
            s >= next - weights.PrepareMeters)
            return UseReference("cyclic-bend-reference", 0, "reference");

        var activation = Predict(input, crank, RiderController.ReactionSeconds(spec)).Points[^1].Rider;
        double at = activation.TotalReferenceMeters;
        double exitBlend = Smooth((at - bend.Exit + lead) / (lead + 3));
        double entryBlend = Smooth((next - at - weights.PrepareMeters) / 12);
        double blend = exitBlend * entryBlend;
        if (blend <= 0)
            return UseReference(at < bend.Exit ? "exit-preparation" : "entry-preparation", 0, "reference");

        var mode = at < bend.Exit ? "exit-preparation" : entryBlend < 1 ? "entry-preparation" : "straight";
        var previous = input.Pending.Length == 0 ? input.Active : input.Pending[^1].Action;
        float limit = TwoContactBikeParameters.Default.MaximumSteeringRadians;
        float gas = Mix(original.Drive, 1, blend);
        Trace173.Event("exit-boost", new { input.Time, at, next, blend, gas, original });
        FreeRacingAction? FindSteering(float drive)
        {
            double bestScore = double.PositiveInfinity;
            var best = original;
            void Try(float target)
            {
                float steer = Math.Clamp(Mix(original.SteeringRadians, target, blend), -limit, limit);
                var action = new FreeRacingAction(steer, drive);
                var points = Predict(input, crank, ShortSeconds, action).Points;
                if (!Legal(points)) { Trace173.Event("exit-candidate", new { action, Legal = false }); return; }
                var score = Score(points, bend, next, steer - previous.SteeringRadians);
                Trace173.Event("exit-candidate", new { action, Legal = true, score });
                if (score < bestScore)
                {
                    bestScore = score;
                    best = action;
                }
            }
            foreach (float target in SteerGrid) Try(target);
            if (!double.IsFinite(bestScore)) return null;
            float center = (best.SteeringRadians - original.SteeringRadians * (float)(1 - blend)) / (float)blend;
            foreach (float delta in new[] { -.003f, -.0015f, .0015f, .003f }) Try(center + delta);
            return best;
        }

        Review RollOff(string gate)
        {
            // Steering correction is still needed while the delayed drive rolls off.
            // The backup uses the original gas law and replans from the accepted state.
            var controlled = tuning.StabilizeRelease ? FindSteering(original.Drive) : null;
            return controlled is { } action ? Result(action, mode, blend, "roll-off:" + gate) :
                UseReference(mode, blend, gate);
        }

        if (!CanPrepare(activation, next))
            return RollOff("entry-speed-budget");

        if (FindSteering(gas) is not { } best)
            return RollOff("short-clearance");

        double nextCrank = crank.Omega;
        var review = Predict(input, crank, ReviewSeconds, best, (_, omega) => nextCrank = omega).Points[^1];
        var delay = RiderController.ReactionSeconds(spec);
        var pending = input.Pending.Where(c => c.ActivationAt > review.Time + 1e-9)
            .Append(new(input.Time, input.Time + delay, best)).ToArray();
        var nextInput = new FreeRacingInput(review.Rider, review.Time, review.Omega, review.Steering,
            input.Pending.Where(c => c.ActivationAt <= review.Time + 1e-9).Select(c => c.Action)
                .Prepend(input.Active).Last(), pending, review.Time);
        var shaft = new CrankClutch144(crank.Parameters, nextCrank);
        var release = Baseline(nextInput, shaft);
        // A next-review correction is allowed to react to the propagated state. Gas can roll off
        // through the ordinary delay. A short pulse is admitted only with a legal way out.
        foreach (float correction in new[] { best.SteeringRadians, release.SteeringRadians, 0f, -.004f, .004f }.Distinct())
        {
            var followUp = release with { SteeringRadians = correction };
            var tail = Predict(nextInput, shaft, CheckSeconds - ReviewSeconds, followUp).Points;
            bool legal = Legal(tail);
            bool prepare = legal && CanPrepare(tail[^1].Rider, next, checkPulse: false);
            bool settled = prepare && Settled(tail, bend, next);
            Trace173.Event("continuation-gate", new { followUp, legal, PrepareEvaluated = legal,
                prepare, SettledEvaluated = prepare, settled });
            if (legal && prepare && settled)
            {
                plannedRelease = followUp;
                releaseReview = review.Time;
                return Result(best, mode, blend, "accepted");
            }
        }
        return RollOff("continuation");

        Review UseReference(string mode, double mix, string gate) =>
            Result(fallback ?? original, mode, mix, fallback.HasValue ? "planned-release:" + gate : gate);

        Review Result(FreeRacingAction action, string mode, double mix, string gate)
        {
            Trace173.Event("exit-result", new { input.Time, original, action, mode, mix, gate, fallback });
            lastProposed = action;
            return new(input.Time, s, mode, original, action, mix, gate, forecasts, queries,
                predictionTicks * 1000d / Stopwatch.Frequency);
        }
    }

    private FreeRacingAction Baseline(FreeRacingInput input, CrankClutch144 crank)
    {
        long start = Stopwatch.GetTimestamp();
        long before = baseline.ForecastContactQueries;
        var action = baseline.Choose(input, crank);
        if (baseline.ForecastContactQueries > before)
        {
            predictionTicks += Stopwatch.GetTimestamp() - start;
            forecasts++;
            queries += checked((int)(baseline.ForecastContactQueries - before));
        }
        return action;
    }

    private FreeRacingPrediction Predict(FreeRacingInput input, CrankClutch144 crank, double horizon,
        FreeRacingAction? candidate = null, Action<double, double>? observe = null)
    {
        long start = Stopwatch.GetTimestamp();
        var result = PredictorA153.Predict(input, spec, frame, surface, parameters, mass, inertia,
            horizon, candidate: candidate, powertrain: crank, boundaryCache: cache, fastBoundary: boundary,
            exactInitialWheel: true, observeCrank: observe);
        Trace173.Prediction("exit", input, horizon, candidate, result);
        predictionTicks += Stopwatch.GetTimestamp() - start;
        forecasts++;
        queries += result.ForceEvaluations;
        return result;
    }

    private bool CanPrepare(RiderView bike, double entry, bool checkPulse = true)
    {
        double seconds = checkPulse ? ReviewSeconds : 0;
        double speed = bike.Speed + PreviewAcceleration * seconds;
        double remaining = Math.Max(0, entry - bike.TotalReferenceMeters - speed * seconds);
        double entrySpeed = targets.FlyingEntrySpeed + tuning.SpeedHeadroom;
        bool accepted = speed * speed <= entrySpeed * entrySpeed + 2 * CoastMetersPerSecondSquared * remaining;
        Trace173.Event("can-prepare", new { checkPulse, Entry = entry, Reference = bike.TotalReferenceMeters,
            ActualSpeed = bike.Speed, PulseSpeed = speed, Remaining = remaining, EntrySpeed = entrySpeed,
            Deceleration = CoastMetersPerSecondSquared,
            AllowedSpeed = Math.Sqrt(entrySpeed * entrySpeed + 2 * CoastMetersPerSecondSquared * remaining),
            RequiredDeceleration = remaining > 0 ? Math.Max(0, (speed * speed - entrySpeed * entrySpeed) / (2 * remaining)) : (double?)null,
            Accepted = accepted });
        return accepted;
    }

    private static bool Legal(FreeRacingPoint[] points)
    {
        for (int i = 1; i < points.Length; i++)
        {
            var a = points[i - 1];
            var b = points[i];
            if (Math.Abs(b.Rider.SlideRadians) > Math.PI / 4 ||
                Clearance153.SweepLowerBound(a.Rider, b.Rider, b.Time - a.Time,
                    (a.Inner, a.Outer), (b.Inner, b.Outer)) < PredictedSweepMeters)
                return false;
        }
        return true;
    }

    private ProfilePoint Learned(double s) => Teacher.Blend(a.At(s), b.At(s), weights.Blend);

    private ProfilePoint Reference(double s, Bend bend, double next) => targets.Stability(s);

    private double Score(FreeRacingPoint[] points, Bend bend, double next, double steeringChange)
    {
        var bike = points[^1].Rider;
        var target = Reference(bike.TotalReferenceMeters, bend, next);
        double offset = bike.Road.OffsetMeters - target.Offset;
        double courseError = BikeAngles.Wrap(Teacher.CourseError(bike) - target.Course - Math.Atan(offset / 10));
        double headingError = BikeAngles.Wrap(bike.Heading - bike.Road.Heading - target.Course - target.Beta);
        double beta = BikeAngles.Wrap(bike.SlideRadians - target.Beta);
        double yaw = bike.AngularVelocity - target.Yaw;
        double outward = Vector2.Dot(bike.Velocity, bike.Road.Outward) + bike.Speed * Math.Sin(target.Course);
        return 2.2 * Square(courseError) + .15 * Square(headingError) + .015 * Square(offset)
            + .009 * Square(outward) + 2.5 * Square(beta) + .22 * Square(yaw)
            + .018 * Square(BetaRate(points, bend, next)) + .4 * Square(steeringChange);
    }

    private bool Settled(FreeRacingPoint[] points, Bend bend, double next)
    {
        var bike = points[^1].Rider;
        var target = Reference(bike.TotalReferenceMeters, bend, next);
        double beta = BikeAngles.Wrap(bike.SlideRadians - target.Beta);
        double rate = BetaRate(points, bend, next);
        double betaGate = Math.Abs(beta) + .2 * Math.Max(0, rate * Math.Sign(beta));
        double yawGate = Math.Abs(bike.AngularVelocity - target.Yaw);
        double courseGate = Math.Abs(BikeAngles.Wrap(Teacher.CourseError(bike) - target.Course));
        Trace173.Event("settled", new { beta, rate, betaGate, yawGate, courseGate });
        return betaGate < .17 && yawGate < .48 && courseGate < .21;
    }

    private double BetaRate(FreeRacingPoint[] points, Bend bend, double next)
    {
        var end = points[^1];
        var previous = points[^2];
        double Error(FreeRacingPoint point) =>
            point.Rider.SlideRadians - Reference(point.Rider.TotalReferenceMeters, bend, next).Beta;
        return BikeAngles.Wrap(Error(end) - Error(previous)) / (end.Time - previous.Time);
    }

    private static double Square(double x) => x * x;
    private static float Mix(float a, float b, double mix) => (float)(a + (b - a) * mix);
    private static double Smooth(double x)
    {
        double u = Math.Clamp(x, 0, 1);
        return u * u * (3 - 2 * u);
    }
}

